This hack fix would seem to work, but then there's another issue in mailer so I'll open another issue
(implementing `__toString` and type casting as a string in `__wakeup()`
```
public function __wakeup()
    {
        $r = new \ReflectionProperty(AbstractPart::class, 'headers');
        $r->setValue($this, $this->_headers);
        unset($this->_headers);

        if (!\is_array($this->_parent)) {
            throw new \BadMethodCallException('Cannot unserialize '.__CLASS__);
        }
        foreach (['body', 'charset', 'subtype', 'disposition', 'name', 'encoding'] as $name) {
            if (null !== $this->_parent[$name] && !\is_string((string) $this->_parent[$name])) {
                throw new \BadMethodCallException('Cannot unserialize '.__CLASS__);
            }
            $r = new \ReflectionProperty(TextPart::class, $name);
            $r->setValue($this, $this->_parent[$name]);
        }
        unset($this->_parent);
    }
```

```
class BodyFile
{
    private static $mimeTypes;

    public function __construct(
        private string $path,
    ) {
    }

    public function getPath(): string
    {
        return $this->path;
    }

    public function getContentType(): string
    {
        $ext = strtolower(pathinfo($this->path, \PATHINFO_EXTENSION));
        if (null === self::$mimeTypes) {
            self::$mimeTypes = new MimeTypes();
        }

        return self::$mimeTypes->getMimeTypes($ext)[0] ?? 'application/octet-stream';
    }
    
    public function __toString() {
        return $this->getPath();
    }
}
```

